import java.util.*;class Solution{Map<String,PriorityQueue<String>>g=new HashMap<>();LinkedList<String>o=new LinkedList<>();void f(String u){PriorityQueue<String>q=g.get(u);while(q!=null&&!q.isEmpty())f(q.remove());o.addFirst(u);}public List<String> findItinerary(List<List<String>>t){for(List<String>x:t)g.computeIfAbsent(x.get(0),k->new PriorityQueue<>()).add(x.get(1));f("JFK");return o;}}
